+  const stop = (options.interval ?? defaultInterval)(poll, options.pollMs ?? PROJECT_CONTEXT_POLL_MS);
+  return {
+    current: () => current,
+    reload,
+    subscribe: (listener) => {
+      listeners.add(listener);
+      return () => void listeners.delete(listener);
